using System.Text;
using System.Text.Json;

namespace Chaos.IL2CPP.Tools.AutoTestGenerator;

public sealed class ProjectWriter
{
    public void WriteAll(
        string outputDir,
        string assemblyName,
        string typeFullName,
        string autoGeneratedSource,
        IReadOnlyList<ProbeResult> probeResults,
        CoverageReport report,
        string targetFramework = "net8.0")
    {
        Directory.CreateDirectory(outputDir);

        // 1. AutoGenerated.cs
        // Strip generic args before extracting short name, so that
        // "System.Collections.Generic.List<System.Int32>" → "List" (not "Int32>").
        var gaIdx = typeFullName.IndexOf('<');
        var baseName = gaIdx >= 0 ? typeFullName[..gaIdx] : typeFullName;
        var lastDot = baseName.LastIndexOf('.');
        var shortName = lastDot >= 0 ? baseName[(lastDot + 1)..] : baseName;
        var typeShortName = SanitizeFileName(shortName);
        var csPath = Path.Combine(outputDir, $"{typeShortName}.AutoGenerated.cs");
        File.WriteAllText(csPath, autoGeneratedSource);
        Console.WriteLine($"[Output] {csPath}");

        // 2. Program.cs (entry point — discovers [Fact] methods and runs them)
        var programPath = Path.Combine(outputDir, "Program.cs");
        File.WriteAllText(programPath, GenerateProgramCs(typeFullName));
        Console.WriteLine($"[Output] {programPath}");

        // 3. .csproj
        var csprojPath = Path.Combine(outputDir, $"{typeShortName}.csproj");
        File.WriteAllText(csprojPath, GenerateCsproj(assemblyName, targetFramework));
        Console.WriteLine($"[Output] {csprojPath}");

        // 4. probe-results.json
        var probePath = Path.Combine(outputDir, "probe-results.json");
        var probeJson = JsonSerializer.Serialize(probeResults, new JsonSerializerOptions
        {
            WriteIndented = true,
            PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
        });
        File.WriteAllText(probePath, probeJson);
        Console.WriteLine($"[Output] {probePath}");

        // 5. README.md
        var readmePath = Path.Combine(outputDir, "README.md");
        File.WriteAllText(readmePath, GenerateReadme(report));
        Console.WriteLine($"[Output] {readmePath}");
    }

    private string GenerateProgramCs(string typeFullName)
    {
        return
            "// Auto-generated test runner\n" +
            "using System.Reflection;\n" +
            "using Chaos.TestFramework;\n" +
            "\n" +
            "var testType = typeof(Program).Assembly.GetTypes().FirstOrDefault(t => t.Name.EndsWith(\"Tests\"));\n" +
            "if (testType is null) { Console.Error.WriteLine(\"[FATAL] Test class not found\"); return 1; }\n" +
            "\n" +
            "object? instance = null;\n" +
            "if (!testType.IsAbstract && testType.GetConstructors().Any(c => c.GetParameters().Length == 0))\n" +
            "    instance = Activator.CreateInstance(testType);\n" +
            "\n" +
            "int passed = 0, failed = 0;\n" +
            "foreach (var method in testType.GetMethods(BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Static | BindingFlags.Instance))\n" +
            "{\n" +
            "    if (method.GetCustomAttribute<FactAttribute>() is null) continue;\n" +
            "    if (method.GetParameters().Length != 0) continue;\n" +
            "    try\n" +
            "    {\n" +
            "        method.Invoke(method.IsStatic ? null : instance, null);\n" +
            "        Console.WriteLine($\"[PASS] {testType.Name}.{method.Name}\");\n" +
            "        passed++;\n" +
            "    }\n" +
            "    catch (TargetInvocationException ex) when (ex.InnerException is not null)\n" +
            "    {\n" +
            "        var msg = ex.InnerException.Message;\n" +
            "        Console.WriteLine($\"[FAIL] {testType.Name}.{method.Name}: {msg}\");\n" +
            "        failed++;\n" +
            "    }\n" +
            "    catch (Exception ex)\n" +
            "    {\n" +
            "        Console.WriteLine($\"[FAIL] {testType.Name}.{method.Name}: {ex.Message}\");\n" +
            "        failed++;\n" +
            "    }\n" +
            "}\n" +
            "\n" +
            "Console.WriteLine($\"Summary: {passed} passed, {failed} failed\");\n" +
            "return failed > 0 ? 1 : 0;\n";
    }

    private string GenerateCsproj(string assemblyName, string targetFramework)
    {
        var sdkDir = Path.GetFullPath(
            Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "..", "..",
                         "src", "reference", "Chaos.TestFramework.Sdk",
                         "Chaos.TestFramework.Sdk.csproj"));

        return
            "<Project Sdk=\"Microsoft.NET.Sdk\">\n" +
            "  <PropertyGroup>\n" +
            "    <OutputType>Exe</OutputType>\n" +
           $"    <TargetFramework>{targetFramework}</TargetFramework>\n" +
            "    <ImplicitUsings>enable</ImplicitUsings>\n" +
            "    <Nullable>enable</Nullable>\n" +
            "    <AllowUnsafeBlocks>true</AllowUnsafeBlocks>\n" +
            "  </PropertyGroup>\n" +
            "  <ItemGroup>\n" +
           $"    <ProjectReference Include=\"{sdkDir}\" />\n" +
            "  </ItemGroup>\n" +
            "</Project>\n";
    }

    private string GenerateReadme(CoverageReport report)
    {
        var sb = new StringBuilder();
        sb.AppendLine($"# AutoTestGenerator: {report.TypeName}");
        sb.AppendLine();
        sb.AppendLine($"- Assembly: `{report.AssemblyName}`");
        sb.AppendLine($"- Type: `{report.TypeName}`");
        sb.AppendLine();
        sb.AppendLine("## Coverage Summary");
        sb.AppendLine();
        sb.AppendLine($"| Metric | Value |");
        sb.AppendLine($"|--------|-------|");
        sb.AppendLine($"| Total Methods | {report.TotalMethods} |");
        sb.AppendLine($"| Auto-generated (Fact + Benchmark + HotUpdate) | {report.AutoGeneratedMethods} |");
        sb.AppendLine($"| Benchmark-only (pure void / non-deterministic) | {report.BenchmarkOnlyMethods} |");
        sb.AppendLine($"| Skipped (generic / unresolvable) | {report.SkippedMethods} |");
        sb.AppendLine($"| Total Subjects | {report.TotalSubjects} |");
        sb.AppendLine();
        sb.AppendLine("## Build");
        sb.AppendLine();
        sb.AppendLine("```bash");
        sb.AppendLine("# Build with verification (Assert enabled)");
        sb.AppendLine("dotnet build -p:DefineConstants=VERIFY");
        sb.AppendLine();
        sb.AppendLine("# Build for benchmark (Assert eliminated)");
        sb.AppendLine("dotnet build");
        sb.AppendLine("```");
        sb.AppendLine();
        sb.AppendLine("## Run");
        sb.AppendLine();
        sb.AppendLine("```bash");
        sb.AppendLine("# Run with verification");
        sb.AppendLine("dotnet run --project .");
        sb.AppendLine("```");

        if (report.SkippedMethodNames.Count > 0)
        {
            sb.AppendLine();
            sb.AppendLine("## Skipped Methods");
            sb.AppendLine();
            foreach (var name in report.SkippedMethodNames)
                sb.AppendLine($"- `{name}` — contains generic parameters, needs manual handling");
        }

        return sb.ToString();
    }

    private static string SanitizeFileName(string name)
    {
        return name.Replace('<', '_').Replace('>', '_').Replace('`', '_');
    }
}
